sorter = Sorter()
sorter.set_strategy(BubbleSort())
print(f"Bubble: {sorter.sort(data)}")
sorter.set_strategy(QuickSort())
print(f"Quick:  {sorter.sort(data)}")
sorter.set_strategy(MergeSort())
print(f"Merge:  {sorter.sort(data)}")

