def lcs_length(s1, s2):
    m = len(s1)
    n = len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp


def lcs_traceback(dp, s1, s2):
    i = len(s1)
    j = len(s2)
    result = []
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            result.append(s1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    result.reverse()
    return "".join(result)


def lcs(s1, s2):
    dp = lcs_length(s1, s2)
    return lcs_traceback(dp, s1, s2)


def lcs_all(s1, s2):
    dp = lcs_length(s1, s2)
    length = dp[len(s1)][len(s2)]
    results = set()

    def backtrack(i, j, current):
        if len(current) == length:
            results.add("".join(reversed(current)))
            return
        if i == 0 or j == 0:
            return
        if s1[i - 1] == s2[j - 1]:
            backtrack(i - 1, j - 1, current + [s1[i - 1]])
        else:
            if dp[i - 1][j] >= dp[i][j - 1]:
                backtrack(i - 1, j, current)
            if dp[i][j - 1] >= dp[i - 1][j]:
                backtrack(i, j - 1, current)

    backtrack(len(s1), len(s2), [])
    return results


